entries[116184] = { ["name"] = "Kriegswerkstatt, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Kriegswerkstatt bauen könnt.\n\nLevel 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\nLevel 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\nLevel 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nVerkaufspreis:" }
entries[116185] = { ["name"] = "Kriegswerkstatt, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Kriegswerkstatt auf Stufe 2 ausbauen könnt.\n\nLevel 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\nLevel 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\nLevel 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[116186] = { ["name"] = "Kriegswerkstatt, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Kriegswerkstatt auf Stufe 3 ausbauen könnt.\n\nLevel 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\nLevel 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\nLevel 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nBenötigt den Erfolg \"Die Reihen füllen\".\nVerkaufspreis:" }
