entries[116196] = { ["name"] = "Geisterhaus, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Geisterhaus auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\nLevel 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\nLevel 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[116197] = { ["name"] = "Geisterhaus, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Geisterhaus auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\nLevel 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\nLevel 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nBenötigt den Erfolg \"Portalsteine schlagen Portalscheren\".\nVerkaufspreis:" }
entries[116198] = { ["name"] = "Geisterhaus, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Geisterhaus bauen könnt.\n\nLevel 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\nLevel 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\nLevel 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nVerkaufspreis:" }
entries[116199] = { ["name"] = "Goblinwerkstatt, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Goblinwerkstatt bauen könnt.\n\nLevel 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\nLevel 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\nLevel 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nVerkaufspreis:" }
entries[116200] = { ["name"] = "Goblinwerkstatt, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Goblinwerkstatt auf Stufe 2 ausbauen könnt.\n\nLevel 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\nLevel 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\nLevel 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[116201] = { ["name"] = "Goblinwerkstatt, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Goblinwerkstatt auf Stufe 3 ausbauen könnt.\n\nLevel 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\nLevel 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\nLevel 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nBenötigt den Erfolg \"Tödliche Technik\".\nVerkaufspreis:" }
