entries[116247] = { ["name"] = "Frostwallmine", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Frostwallmine bauen könnt.\n\nLevel 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\nLevel 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:" }
entries[116248] = { ["name"] = "Frostwallmine, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Frostwallmine auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\nLevel 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt Mine\nVerkaufspreis:" }
entries[116249] = { ["name"] = "Frostwallmine, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Frostwallmine auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\nLevel 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Sammler draenischer Steine\".\nVerkaufspreis:" }
