entries[116410] = { ["name"] = "Schriftrolle der Geschwindigkeit", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Erhöht 8 Sek. lang Eure und die Bewegungsgeschwindigkeit aller verbündeten Ziele in der Nähe um 70%. Spielercharaktere können nicht mehr als eine Schriftrolle der Geschwindigkeit gleichzeitig aktivieren. (1 Min, 30 Sek. Abklingzeit)" }
entries[116411] = { ["name"] = "Rolle des Schutzes", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Verringert 15 Sek. lang den Schaden, den Ihr und alle verbündeten Ziele in der Nähe erleidet, um 60%. Spielercharaktere können nicht mehr als eine Schriftrolle des Schutzes gleichzeitig aktivieren. (1 Min, 30 Sek. Abklingzeit)" }
entries[116412] = { ["name"] = "Schriftrolle der Massenunsichtbarkeit", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Macht den Zaubernden und alle Gruppen- und Schlachtzugsmitglieder innerhalb von 25 Metern 20 Sek. lang unsichtbar. Durch Angriffe wird dieser Effekt beendet. (1 Min, 30 Sek. Abklingzeit)" }
entries[116413] = { ["name"] = "Schriftrolle des Stadtportals", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Teleportiert Euch zu Eurer Heimatbasis. (1 Min, 30 Sek. Abklingzeit)" }
