entries[116431] = { ["name"] = "Frostwallschenke, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Frostwallschenke auf Stufe 2 ausbauen könnt.\n\nLevel 1\nQuartiert jeden Tag einen Abenteurer in Eurem Gasthaus ein, der eine Dungeonquest mit großzügigen Belohnungen anbietet.\n\nLevel 2\nHeuert jede Woche zufällige Anhänger an. Ihr könnt bestimmte Eigenschaften und Fähigkeiten angeben, an denen Ihr besonders interessiert seid.\n\nLevel 3\nSchaltet die besonders lukrativen Missionen für Garnisonsressourcen frei.\nBenötigt den Abschluss der Außenpostenquests in den Spitzen von Arak oder Stufe 30.\nVerkaufspreis:" }
entries[116432] = { ["name"] = "Frostwallschenke, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Frostwallschenke auf Stufe 3 ausbauen könnt.\n\nLevel 1\nQuartiert jeden Tag einen Abenteurer in Eurem Gasthaus ein, der eine Dungeonquest mit großzügigen Belohnungen anbietet.\n\nLevel 2\nHeuert jede Woche zufällige Anhänger an. Ihr könnt bestimmte Eigenschaften und Fähigkeiten angeben, an denen Ihr besonders interessiert seid.\n\nLevel 3\nSchaltet die besonders lukrativen Missionen für Garnisonsressourcen frei.\nBenötigt den Erfolg \"Bleibt ein Weilchen und hört zu\".\nVerkaufspreis:" }
entries[116433] = { ["name"] = "Frostwallschenke, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Frostwallschenke bauen könnt.\n\nLevel 1\nQuartiert jeden Tag einen Abenteurer in Eurem Gasthaus ein, der eine Dungeonquest mit großzügigen Belohnungen anbietet.\n\nLevel 2\nHeuert jede Woche zufällige Anhänger an. Ihr könnt bestimmte Eigenschaften und Fähigkeiten angeben, an denen Ihr besonders interessiert seid.\n\nLevel 3\nSchaltet die besonders lukrativen Missionen für Garnisonsressourcen frei.\nVerkaufspreis:" }
