entries[116435] = { ["name"] = "Gemütliches Feuer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Entfacht ein gemütliches Feuer, das die Vielseitigkeit aller in der Nähe um 4 erhöht und das Kochen ermöglicht. (30 Min Abklingzeit)" }
