entries[116439] = { ["name"] = "Lodernder Flammenkrabbler", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren lodernden Flammenkrabbler beschwören oder wieder freigeben.\n80 ( 80)" }
