entries[116646] = { ["name"] = "Stahlgeschmiedeter Hammer", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
