entries[116648] = { ["name"] = "Prisma der synthetischen Liebe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fokussiert das Prisma auf ein Ziel und bringt es vor lauter Verehrung zum Leuchten. (30 Sek. Abklingzeit)\n50 Aufladungen\n\"Enthält einen begrenzten Vorrat an Liebe.\"" }
entries[116649] = { ["name"] = "Instabile Echtstahlessenz", ["text"] = "\"Die Essenz ist instabil geworden.\"" }
entries[116650] = { ["name"] = "Instabile große Echtstahlessenz", ["text"] = "\"Die Essenz ist instabil geworden.\"" }
entries[116651] = { ["name"] = "Prisma der wahren Liebe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Fokussiert das Prisma auf ein Ziel und bringt es vor lauter Verehrung zum Leuchten. (5 Min Abklingzeit)\n\"Die in diesem Objekt enthaltene Liebe ist grenzenlos.\"" }
entries[116652] = { ["name"] = "Instabile stahlgeschmiedete Essenz", ["text"] = "\"Die Essenz ist instabil geworden.\"" }
entries[116653] = { ["name"] = "Instabile große stahlgeschmiedete Essenz", ["text"] = "\"Die Essenz ist instabil geworden.\"" }
entries[116654] = { ["name"] = "Echtstahlschleifer", ["text"] = "Verkaufspreis:" }
entries[116655] = { ["name"] = "Dorrhautklippentrampler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Dorrhautklippentrampler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Bei dieser Grollhufart sind die Hufe mit kleinen Kerben bedeckt, was es ihr erleichtert, ungefährdet Bergregionen auf der Suche nach Nahrung zu erklimmen.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n\n|" }
entries[116656] = { ["name"] = "Zugerittener Eishuf", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren zugerittenen Eishuf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Bevor Euch dieses Reittier gehörte, hattet Ihr ja nicht die geringste Ahnung davon, wie schwer es in Draenor werden würde. Grollhufhaare überall!\"\nHerkunft:\nStall der Garnison" }
entries[116657] = { ["name"] = "Alte Lederhaut", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Eure alte Lederhaut oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten" }
entries[116658] = { ["name"] = "Tundraeishuf", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Tundraeishuf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das durchscheinende Unterfell dieser Art ist eine perfekte Isolierung für den Einsatz in kalten Umgebungen.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel" }
entries[116659] = { ["name"] = "Bluthufbulle", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Bluthufbullen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Schon lange jagen die Mitglieder des Kriegshymnenklans diese Grollhufe, um ihre blutrote Haut für Schlachtstandarten zu verwenden.\"\nBeute von:\nNakk der Donnerer\nOrt:\nNagrand" }
entries[116660] = { ["name"] = "Eisenhufzerstörer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Eisenhufzerstörer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es wird behauptet, dass Schwarzfaust die feurige Rüstung für die Schlachtgrollhufe der Eisernen Horde selbst entworfen hat.\"\nBeute von:\nSchwarzfaust\nOrt:\nSchwarzfelsgießerei (Mythisch)" }
entries[116661] = { ["name"] = "Scheckiger Wiesentrampler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren scheckigen Wiesentrampler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Mit seinem langen Rüssel kann dieser Elekk Nahrung erschnüffeln, Gefahren umgehen und Leckerlis aus Eurer Tasche stibitzen, wenn Ihr gerade nicht hinseht.\"\nBeute von:\nLuk'hok\nZone:\nNagrand" }
entries[116662] = { ["name"] = "Zugerittener Wiesentrampler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren zugerittenen Wiesentrampler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Draenei haben schon vor langer Zeit die Elekkhaltung perfektioniert und schmücken die Kreaturen mit lichtgetränkten Kristallen, um sie gefügig zu machen.\"\nQuest:\nStall der Garnison" }
entries[116663] = { ["name"] = "Schattenfellperlzahn", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Schattenfellperlzahn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einigen Legenden zufolge haben die Draenei sich mit den Elekks angefreundet, nachdem eines dieser wilden Tiere einen verletzten Späher vor einem Rudel bösartiger Schotlinge beschützt hatte.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[116664] = { ["name"] = "Staubige Steinhaut", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Eure staubige Steinhaut oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Exarchenrat\n- Ehrfürchtig\nVerkaufspreis:\n\"Seit Ihr dieses Reittier erworben habt, habt Ihr merkwürdige Fieberträume von einer Parade tanzender und trötender rosa Elekks. Elekks hin, Elekks her, in rosa, da stör'n sie Euch sehr!\"\nVerkäufer:\nVerteidiger Nuurem\nFraktion:\nExarchenrat - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5. + 5.000" }
entries[116665] = { ["name"] = "Gepanzerter Eisenzahn", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren gepanzerten Eisenzahn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Sha'tarverteidigung\n- Ehrfürchtig\nVerkaufspreis:\n\"Es wird behauptet, dass ein Elekk nie etwas vergisst. Es ist also kein Wunder, dass dieses Tier die Eiserne Horde verachtet, wenn man bedenkt, was für Qualen die Orcs ihm angetan haben.\"\nVerkäufer:\n\nFraktion:\nSha'tarverteidigung - Ehrfürchtig\nOrt:\nGarnison - Handelsposten\nKosten:\n5. + 5.000" }
entries[116666] = { ["name"] = "Schwarzstahlkampfeber", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Weigert sich zu rennen, wenn sein Schädel nicht mit schweren Metallstacheln bedeckt ist. Das stärkt sein Ego.\"\nErfolg:\nRuhm des Draenorschlachtzüglers" }
entries[116667] = { ["name"] = "Felshauerkampfeber", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Angelockt werden potenzielle Partner nicht etwa durch den Metallhelm, sondern durch den fetzigen Irokesenschnitt.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n\n|" }
entries[116668] = { ["name"] = "Gepanzerter Frosteber", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren gepanzerten Frosteber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ernährt sich praktisch ausschließlich von gefrorenen Beeren. Gibt sich jedoch auch mit dem Geschmack von langsamen Fremdlingen zufrieden.\"\nErfolg:\nFortgeschrittene Viehhaltung" }
entries[116669] = { ["name"] = "Gepanzerter Klingenrücken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren gepanzerten Klingenrücken oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Passt bloß auf, dass er... NIEMALS... Schinken in Eurer Tasche riecht.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel" }
entries[116670] = { ["name"] = "Frostebenenkampfeber", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Frostebenenkampfeber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ohne dieses coole Hauerpiercing würde er sich in dem Outfit echt bekloppt vorkommen.\"\nErfolg:\nRuhm des Draenorhelden" }
entries[116671] = { ["name"] = "Wilder Geiferzahn", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren wilden Geiferzahn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Säbelzahnpirscher\n- Wohlwollend\n\n\"Wenn Ihr gemütlich reiten möchtet, sucht Euch doch einen \"zahmen Glückshauer\" oder so.\"\nVerkäufer:\nZ'tenga der Wanderer\nZone:\nTanaandschungel\nFraktion:\nDie Säbelzahnpirscher - Wohlwollend\nKosten:\n1.000" }
entries[116672] = { ["name"] = "Domestizierter Klingenrücken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren domestizierten Klingenrücken oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Werterhaltungsgesellschaft des Dampfdruckkartells\n- Ehrfürchtig\nVerkaufspreis:\n\"Domestiziert\" heißt nicht \"freundlich\". Bringt also Leckerlis mit.\nVerkäufer:\nGazrix Kolbenfresser/Mimi Wirbelwolke\nFraktion:\nWerterhaltungsgesellschaft des Dampfdruckkartells - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5. + 5.000" }
entries[116673] = { ["name"] = "Riesige Kaltschnauze", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Eure riesige Kaltschnauze oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schnauze ist nicht nur kalt, sondern auch nass. Es gibt angenehmere Methoden, aufgeweckt zu werden.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[116674] = { ["name"] = "Mächtiger Grauhauer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren mächtigen Grauhauer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wirft seine Hauer einmal im Jahr ab und ist äußert schüchtern, bis sie nachgewachsen sind.\"\nBeute von:\nGorok\nZone:\nFrostfeuergrat" }
entries[116675] = { ["name"] = "Zugerittener Felshauer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren zugerittenen Felshauer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Gründlich darin ausgebildet, wie man schnaubt, trötet und auf den Gesichtern seiner Feinde herumtrampelt.\"\nQuest:\nStall der Garnison" }
entries[116676] = { ["name"] = "Zugerittener Flussfläzer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren zugerittenen Flussfläzer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Flussfläzer gehören zu den kräftigsten Tieren in Draenor, was ihnen mehr Ausdauer und eine markante Färbung verleiht.\"\nQuest:\nStall der Garnison" }
